-- The business profile's one row (D-036; edited in Settings → Business from CR-019): the name,
-- the phones and the logo (a fictional shop with a generated 256 px logo, D-069). The integration
-- setup keeps it.
INSERT INTO "business_profile" ("name", "phones", "logo")
SELECT 'Demo Business Shop', '01700000001, 01800000001', 'data:image/png;base64,'
WHERE NOT EXISTS (SELECT 1 FROM "business_profile");
